    case '{v0}\n\n{v1} history records will be deleted, including {v2} waiting to sync.\n{v3}{v4}\nThis cannot be undone. Copies already uploaded to the cloud remain there.': return l10n.uic2f438460953(value(0), value(1), value(2), value(3), value(4));
