    case 'Troubleshooting cloud setup': return l10n.uia3ce2bacb32e;
    case 'Updating questionnaires online': return l10n.ui693379c73728;
    case 'Use GPS position': return l10n.ui0a045ba7552d;
    case 'WebMap → Layers → Add vector layers. Select multiple shapefile ZIP bundles, or each .shp together with its .dbf/.shx/.prj/.cpg files. GeoJSON FeatureCollections are supported. Reproject layers to WGS84 (EPSG:4326) before importing; missing .prj assumes WGS84. Choose visibility, colour and opacity for each project layer. Reference layers are separate from collected observations, persist locally and travel in project packages and shared HTML maps. Use Explore → Background map to select Street, Imagery, Topographic, Humanitarian, Cycling or No background. Visible vector layers appear in image exports. Import supports up to 64 MB and 50,000 reference features per project.': return l10n.uif202ba19ecbc;
    case 'WebMap, map styling and images': return l10n.ui18f2b9281b8e;
    case 'completed': return l10n.ui231e564db4cd;
